  "No photo stored.": { es: "No hay foto guardada.", ar: "لا توجد صورة محفوظة.", zh: "没有保存的照片。", sw: "Hakuna picha iliyohifadhiwa.", sv: "Inget foto sparat.", de: "Kein Foto gespeichert.", pt: "Nenhuma foto armazenada.", fr: "Aucune photo enregistrée." },
